const PRAZOS = {
  baixa: 72,
  media: 24,
  alta: 8,
  urgente: 2,
}

// Prioridades que contam tempo corrido, nao horas uteis.
const CORRIDAS = new Set(['urgente'])

const INICIO_EXPEDIENTE = 9
const FIM_EXPEDIENTE = 18

function ehDiaUtil(data) {
  const dia = data.getUTCDay()
  return dia !== 0 && dia !== 6
}

function somarHorasUteis(inicio, horas) {
  const atual = new Date(inicio.getTime())
  let restante = horas

  while (restante > 0) {
    atual.setUTCHours(atual.getUTCHours() + 1)

    if (ehDiaUtil(atual) && atual.getUTCHours() > INICIO_EXPEDIENTE && atual.getUTCHours() <= FIM_EXPEDIENTE) {
      restante -= 1
    }
  }

  return atual
}

function prazoDe(prioridade) {
  const horas = PRAZOS[prioridade]
  if (horas === undefined) throw new Error(`prioridade desconhecida: ${prioridade}`)
  return horas
}

function vencimentoDoTicket(abertoEm, prioridade) {
  const inicio = new Date(abertoEm)
  const horas = prazoDe(prioridade)

  if (CORRIDAS.has(prioridade)) {
    return new Date(inicio.getTime() + horas * 60 * 60 * 1000).toISOString()
  }

  return somarHorasUteis(inicio, horas).toISOString()
}

