const CUPONS = {
  PRIMEIRA: { tipo: 'percentual', valor: 10 },
  VOLTA20: { tipo: 'percentual', valor: 20 },
}

const FRETE_PADRAO = 25

function subtotalDe(itens) {
  return itens.reduce((soma, item) => soma + item.preco * item.quantidade, 0)
}

function freteDe(itens) {
  // Acima de 300 o frete ja sai de graca, independentemente de cupom.
  return subtotalDe(itens) >= 300 ? 0 : FRETE_PADRAO
}

function descontoDe(subtotal, cupom) {
  const regra = CUPONS[cupom]
  if (!regra) return 0
  if (regra.tipo === 'percentual') return (subtotal * regra.valor) / 100
  return 0
}

function calcularCarrinho(itens, cupons = []) {
  const subtotal = subtotalDe(itens)
  const frete = freteDe(itens)

  let desconto = 0
  for (const cupom of cupons) desconto += descontoDe(subtotal, cupom)

  const total = Math.max(0, subtotal - desconto + frete)
  return { subtotal, frete, desconto, total }
}

