function dentroDoPeriodo(ticket, desde, ate) {
  if (desde && ticket.criadoEm < desde) return false
  if (ate && ticket.criadoEm > ate) return false
  return true
}

function casaBusca(ticket, termo) {
  const alvo = `${ticket.titulo} ${ticket.solicitante}`.toLowerCase()
  return alvo.includes(termo)
}

function filtrarTickets(tickets, filtros = {}) {
  const { status, prioridade, desde, ate, busca } = filtros
  // Termo em branco e ausencia de termo, igual aos filtros de periodo.
  const termo = (busca ?? '').trim().toLowerCase()

  return tickets.filter((ticket) => {
    if (status && ticket.status !== status) return false
    if (prioridade && ticket.prioridade !== prioridade) return false
    if (!dentroDoPeriodo(ticket, desde, ate)) return false
    if (termo && !casaBusca(ticket, termo)) return false
    return true
  })
}

