const saida = []

// Fora das funcoes de log: e o que permite a assinatura delas nao mudar.
let requisicaoAtual = null

function formatar(nivel, mensagem, dados) {
  // Espalhar condicionalmente evita o campo existir com valor vazio.
  const contexto = requisicaoAtual ? { requisicaoId: requisicaoAtual } : {}
  return JSON.stringify({ nivel, mensagem, ...contexto, ...dados })
}

const log = {
  info(mensagem, dados = {}) {
    saida.push(formatar('info', mensagem, dados))
  },
  erro(mensagem, dados = {}) {
    saida.push(formatar('erro', mensagem, dados))
  },
}

function comRequisicao(id, trabalho) {
  const anterior = requisicaoAtual
  requisicaoAtual = id
  try {
    return trabalho()
  } finally {
    // finally garante a limpeza mesmo se o trabalho lancar erro.
    requisicaoAtual = anterior
  }
}

function linhas() {
  return saida.map((linha) => JSON.parse(linha))
}

function limpar() {
  saida.length = 0
}

