challenges.solution:
let idasAFonte = 0

const cache = new Map()

function chaveDe(filtros) {
  return JSON.stringify(filtros)
}

function consultarFonte(filtros) {
  idasAFonte += 1
  return [{ id: 1, status: filtros.status ?? 'todos' }]
}

function buscarTickets(filtros = {}) {
  const chave = chaveDe(filtros)

  if (cache.has(chave)) return cache.get(chave)

  const resultado = consultarFonte(filtros)
  cache.set(chave, resultado)
  return resultado
}

function ticketAlterado(status) {
  // Remove so as entradas afetadas: limpar tudo devolveria a lentidao que o
  // cache resolveu, a cada alteracao de qualquer ticket.
  for (const chave of [...cache.keys()]) {
    const filtros = JSON.parse(chave)
    if (filtros.status === status || filtros.status === undefined) {
      cache.delete(chave)
    }
  }
}

function contarIdas() {
  return idasAFonte
}

function zerar() {
  cache.clear()
  idasAFonte = 0
}
